    def test_deduplicates(self):
        result = normalize_tags([Tag("work"), Tag("WORK")])
        assert len(result) == 1
        assert result[0].name == "work"

    def test_preserves_order(self):
        result = normalize_tags([Tag("beta"), Tag("alpha")])
        assert [t.name for t in result] == ["beta", "alpha"]

    def test_string_inputs(self):
        result = normalize_tags(["Work", "home"])
        assert [t.name for t in result] == ["work", "home"]

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("work"), "Home"])
        assert [t.name for t in result] == ["work", "home"]

    def test_empty(self):
        assert normalize_tags([]) == []

    def test_invalid_string_raises(self):
        with pytest.raises(ValueError):
            normalize_tags([""])

