from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(
    id: int,
    title: str = "task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at=None,
    tags=None,
    created_at=None,
) -> Task:
    return Task(
        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        created_at=created_at or NOW,
        tags=tags or [],
    )


# ────────────────────────────────────────────── TaskQuery validation


class TestTaskQueryValidation:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_field(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101])
    def test_invalid_limits(self, limit):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=limit)

    def test_negative_offset(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  Work  ")
        assert q.tag == "work"

    def test_search_stripped_to_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_boundary_limit_1(self):
        q = TaskQuery(limit=1)
        assert q.limit == 1

    def test_boundary_limit_100(self):
        q = TaskQuery(limit=100)
        assert q.limit == 100


# ────────────────────────────────────────────── TaskPage.has_more


class TestTaskPage:
    def test_has_more_true(self):
        page = TaskPage(items=[_task(1)], total=5, limit=1, offset=0)
        assert page.has_more is True

    def test_has_more_false_at_end(self):
        page = TaskPage(items=[_task(1)], total=1, limit=20, offset=0)
        assert page.has_more is False

    def test_has_more_false_exact_fit(self):
        items = [_task(1), _task(2)]
        page = TaskPage(items=items, total=2, limit=2, offset=0)
        assert page.has_more is False

    def test_has_more_with_offset(self):
        page = TaskPage(items=[_task(3)], total=3, limit=1, offset=2)
        assert page.has_more is False


# ────────────────────────────────────────────── apply_query filtering


class TestApplyQueryFiltering:
    @pytest.fixture
    def sample_tasks(self):
        past = NOW - timedelta(days=1)
        future = NOW + timedelta(days=1)
        return [
            _task(1, title="Buy milk", status=TaskStatus.PENDING, due_at=past, tags=[Tag("home")]),
            _task(2, title="Write report", status=TaskStatus.DONE, priority=TaskPriority.HIGH),
            _task(3, title="Buy groceries", status=TaskStatus.PENDING, due_at=future, tags=[Tag("home"), Tag("food")]),
        ]

    def test_filter_by_status(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(tag="home"), NOW)
        ids = {t.id for t in page.items}
        assert ids == {1, 3}

    def test_filter_by_search(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="buy"), NOW)
        ids = {t.id for t in page.items}
        assert ids == {1, 3}

    def test_filter_overdue_true(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=True), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(overdue=False), NOW)
        ids = {t.id for t in page.items}
        assert 1 not in ids
        assert 2 in ids  # done (not overdue)
        assert 3 in ids  # future due

    def test_combined_filters(self, sample_tasks):
        page = apply_query(
            sample_tasks,
            TaskQuery(status=TaskStatus.PENDING, tag="food"),
            NOW,
        )
        assert len(page.items) == 1
        assert page.items[0].id == 3

    def test_no_match(self, sample_tasks):
        page = apply_query(sample_tasks, TaskQuery(search="nonexistent"), NOW)
        assert page.total == 0
        assert page.items == []


# ────────────────────────────────────────────── apply_query sorting


class TestApplyQuerySorting:
    def test_sort_by_title_ascending(self):
        tasks = [_task(1, title="Banana"), _task(2, title="Apple"), _task(3, title="Cherry")]
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        titles = [t.title for t in page.items]
        assert titles == ["Apple", "Banana", "Cherry"]

    def test_sort_by_title_descending(self):
        tasks = [_task(1, title="Banana"), _task(2, title="Apple")]
        page = apply_query(tasks, TaskQuery(sort="title", descending=True), NOW)
        assert page.items[0].title == "Banana"

    def test_sort_by_priority(self):
        tasks = [
            _task(1, priority=TaskPriority.LOW),
            _task(2, priority=TaskPriority.HIGH),
            _task(3, priority=TaskPriority.MEDIUM),
        ]
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        priorities = [t.priority for t in page.items]
        assert priorities == [TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW]

    def test_sort_by_due_at_none_last(self):
        future = NOW + timedelta(days=1)
        tasks = [
            _task(1, due_at=None),
            _task(2, due_at=future),
            _task(3, due_at=NOW),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        ids = [t.id for t in page.items]
        assert ids[-1] == 1  # None sorts last

    def test_sort_by_created_at(self):
        t1 = _task(1, created_at=NOW - timedelta(hours=2))
        t2 = _task(2, created_at=NOW - timedelta(hours=1))
        t3 = _task(3, created_at=NOW)
        page = apply_query([t3, t1, t2], TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2, 3]


# ────────────────────────────────────────────── apply_query pagination


class TestApplyQueryPagination:
    @pytest.fixture
    def many_tasks(self):
        return [_task(i, title=f"Task {i}", created_at=NOW + timedelta(seconds=i)) for i in range(1, 11)]

    def test_limit(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond_total(self, many_tasks):
        page = apply_query(many_tasks, TaskQuery(offset=100), NOW)
        assert page.items == []
        assert page.total == 10
        assert page.has_more is False

    def test_empty_input(self):
        page = apply_query([], TaskQuery(), NOW)
        assert page.total == 0
        assert page.items == []
        assert page.has_more is False
"}

