from __future__ import annotations

from datetime import datetime, timezone
from unittest.mock import Mock

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, TaskRepository
from tasks_api.service import TaskService
from tasks_api.app import create_app

# A fixed "now" for deterministic tests.
FIXED_NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture
def fixed_now():
    return FIXED_NOW


@pytest.fixture
def mock_repo():
    """A unittest.mock.Mock that satisfies the TaskRepository protocol."""
    return Mock(spec=TaskRepository)


@pytest.fixture
def in_memory_repo():
    return InMemoryTaskRepository()


@pytest.fixture
def service(mock_repo, fixed_now):
    """TaskService wired to a mock repository and a fixed clock."""
    return TaskService(mock_repo, now=lambda: fixed_now)


@pytest.fixture
def live_service(in_memory_repo, fixed_now):
    """TaskService wired to a real InMemoryTaskRepository."""
    return TaskService(in_memory_repo, now=lambda: fixed_now)


@pytest.fixture
def app(live_service):
    """Flask test app backed by the in-memory service."""
    return create_app(service=live_service)


@pytest.fixture
def client(app):
    return app.test_client()


def make_task(
    id: int = 1,
    title: str = "Test task",
    status: TaskStatus = TaskStatus.PENDING,
    priority: TaskPriority = TaskPriority.MEDIUM,
    due_at=None,
    completed_at=None,
    created_at=None,
    tags=None,
) -> Task:
