        id=id,
        title=title,
        status=status,
        priority=priority,
        due_at=due_at,
        completed_at=completed_at,
        created_at=created_at or FIXED_NOW,
        tags=tags or [],
    )

"""Tests for tasks_api.models — Task, Tag, TaskStatus, TaskPriority."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ────────────────────────────────────────────── TaskStatus / TaskPriority enums


class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_is_str_enum(self):
        assert isinstance(TaskStatus.PENDING, str)


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_before_low(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(
            TaskPriority.LOW
        )

    def test_order_key_medium_between(self):
        high = TaskPriority.order_key(TaskPriority.HIGH)
        med = TaskPriority.order_key(TaskPriority.MEDIUM)
        low = TaskPriority.order_key(TaskPriority.LOW)
        assert high < med < low


# ────────────────────────────────────────────── Tag


class TestTag:
    def test_normalizes_to_lowercase(self):
        assert Tag("Urgent").name == "urgent"

    def test_strips_whitespace(self):
        assert Tag("  work  ").name == "work"

    @pytest.mark.parametrize("name", ["", "   "])
    def test_empty_raises(self, name):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag(name)

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    @pytest.mark.parametrize("name", ["has space", "no@at", "no.dot"])
    def test_illegal_characters_raises(self, name):
        with pytest.raises(ValueError, match="illegal character"):
            Tag(name)

    @pytest.mark.parametrize("name", ["ok-tag", "under_score", "abc123"])
    def test_allowed_characters(self, name):
        assert Tag(name).name == name

    def test_max_length_boundary(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32


# ────────────────────────────────────────────── Task.is_overdue


class TestTaskIsOverdue:
    NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)

    def test_no_due_date_not_overdue(self):
        task = Task(id=1, title="t", due_at=None)
        assert task.is_overdue(self.NOW) is False

    def test_done_task_not_overdue(self):
        task = Task(
            id=1,
            title="t",
            status=TaskStatus.DONE,
            due_at=self.NOW - timedelta(days=1),
        )
        assert task.is_overdue(self.NOW) is False

    def test_pending_past_due_is_overdue(self):
        task = Task(id=1, title="t", due_at=self.NOW - timedelta(hours=1))
        assert task.is_overdue(self.NOW) is True

    def test_pending_future_due_not_overdue(self):
        task = Task(id=1, title="t", due_at=self.NOW + timedelta(hours=1))
        assert task.is_overdue(self.NOW) is False

    def test_due_at_exactly_now_not_overdue(self):
        task = Task(id=1, title="t", due_at=self.NOW)
        assert task.is_overdue(self.NOW) is False

